properties.default:
(row?: any, index?: any): number => {
    if (!this.rowDetail) {
      return 0;
    }
    const rowHeight = this.rowDetail.rowHeight;
    return typeof rowHeight === 'function' ? rowHeight(row, index) : (rowHeight as number);
  }

inputs.description:
This attribute allows the user to set a grouped array in the following format:
 [
   {groupid=1} [
     {id=1 name="test1"},
     {id=2 name="test2"},
     {id=3 name="test3"}
   ]},
   {groupid=2>[
     {id=4 name="test4"},
     {id=5 name="test5"},
     {id=6 name="test6"}
   ]}
 ]

inputs.default:
{
    // Message to show when array is presented
    // but contains no values
    emptyMessage: this.translateService.instant('DATATABLE.EMPTYMESSAGE'),

    // Footer total message
    totalMessage: this.translateService.instant('DATATABLE.TOTAL'),

    // Footer selected message
    selectedMessage: this.translateService.instant('DATATABLE.SELECTED'),
  }

